structureCode.vanilla:
createSeparator({ orientation: 'horizontal' });
createSeparator({ orientation: 'vertical', decorative: false });
createSeparator({ emphasis: 'strong' });

extensibilityCode.react:
// A classe extra convive com a base; ela não substitui .nds-separator
<Separator className="nds-mt-4" />

// Linha de peso maior entre blocos de assunto diferente
<Separator emphasis="strong" />

extensibilityCode.vanilla:
// A classe extra convive com a base; ela não substitui .nds-separator
createSeparator({ className: 'nds-mt-4' });

// Linha de peso maior entre blocos de assunto diferente
createSeparator({ emphasis: 'strong' });

customizationCode.web:
/* A cor da linha sai de --border; o override troca o token, não a regra */
.tema-custom .nds-separator {
  background-color: hsl(var(--accent));
}

/* A ênfase forte tem regra própria, com espessura e cor separadas */
.tema-custom .nds-separator[data-emphasis="strong"] {
  background-color: hsl(var(--accent) / 0.4);
}

